import json
import requests
import chardet

API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Request failed: {e}")

    content_bytes = response.content
    if not content_bytes:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content_bytes)
        from_encoding = detected.get("encoding")
        if from_encoding is None:
            raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded = content_bytes.decode(from_encoding)
        reencoded = decoded.encode(to_encoding)
        parsed = json.loads(reencoded)
        return parsed
    except (UnicodeDecodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Error processing content: {e}")

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url or not isinstance(repo_url, str):
        raise ValueError("Invalid repository URL provided.")
    try:
        response = requests.get(repo_url, timeout=10, verify=False)
        response.raise_for_status()
        repo_info = response.json()
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 403 and "rate limit" in str(e).lower():
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")
    open_issues = repo_info.get("open_issues_count", 0)
    if open_issues > 100:
        logging.warning(f"Repository has {open_issues} open issues, exceeding threshold of 100.")
    return repo_info

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
        soup = BeautifulSoup(response.content, 'html.parser')
        script_tags = soup.find_all('script')
        dictionaries = []
        for script in script_tags:
            try:
                content = script.string
                if content:
                    parsed = ast.literal_eval(content.strip())
                    if isinstance(parsed, dict):
                        dictionaries.append(parsed)
            except (SyntaxError, ValueError):
                continue
        return dictionaries
    except requests.RequestException:
        return []

