import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise Exception(f"Failed to access the API endpoint: {e}")
    if not isinstance(data, list):
        raise Exception("Invalid data format from API.")
    if not data:
        raise Exception("Empty data received.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to create DataFrame: {e}")
    numerical_columns = df.select_dtypes(include=['int64', 'float64']).columns
    if len(numerical_columns) < 2:
        raise Exception("Insufficient numerical columns for correlation heatmap.")
    corr_matrix = df[numerical_columns].corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr_matrix, ax=ax, annot=True, cmap='coolwarm')
    return df, ax

